  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Brigatinib, a structurally related anilinopyrimidine kinase inhibitor with a piperazine-containing side chain, has an estimated oral bioavailability of 46% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Linezolid, a small synthetic oral antibacterial, has ~100% absolute oral bioavailability, demonstrating that well-absorbed small-molecule drugs in this general property space can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone, a heteroaromatic CNS drug with a basic amine and extended-release formulation, has 28% absolute oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Ketanserin, an aryl ketone piperidine drug, has 46.8% absolute oral bioavailability in healthy subjects, supporting high F for a lipophilic heteroaromatic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Apalutamide, an oral anticancer agent with heteroaromatic and amide motifs, has ~100% absolute oral bioavailability, supporting high F for the query's structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Tacrolimus has an oral bioavailability of approximately 20–25%, which is at or above the F ≥ 20% threshold and does not support a low-F prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic heteroaromatic oral drug-like molecule with no direct bioavailability record, but the strongest transferable evidence from structurally related kinase inhibitors and similar oral small molecules consistently shows absolute oral bioavailability at or above 20%; therefore the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule.",
    "Several records are from different chemical series or formulations, so quantitative transferability is uncertain.",
    "One qualitative 'good bioavailability' record lacks a numeric F value and cannot be threshold-verified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

